import subprocess,json
from pathlib import Path
root=Path('/root/sidereal_spacetime');out=root/'output/playwright/planet-reference-20260914/shadow-followup'
code='''async(page)=>{const result=await page.evaluate(()=>{const r=window.planetReview;r.engine.stopRenderLoop();r.camera.alpha-=1.6;const lights=r.scene.lights.filter(l=>l.getShadowGenerator());return {shadows:lights.map(l=>({name:l.name,normal:l.getShadowGenerator().normalBias,bias:l.getShadowGenerator().bias})),meshes:r.scene.meshes.filter(m=>m.isEnabled()).map(m=>({name:m.name,tri:m.getTotalIndices()/3,role:m.metadata,material:m.material?.name}))}});console.log(JSON.stringify(result));const r=await page.evaluate(()=>{const r=window.planetReview;for(const l of r.scene.lights){const s=l.getShadowGenerator();if(s){s.forceBackFacesOnly=true;s.normalBias=0;s.bias=.0005;}}r.scene.render();});await page.screenshot({path:OUT+'/ice-backfaces.png'});await page.evaluate(()=>{window.planetReview.scene.shadowsEnabled=false;window.planetReview.scene.render()});await page.screenshot({path:OUT+'/ice-no-shadows.png'});}'''.replace('OUT',json.dumps(str(out)))
p=subprocess.run(['bash',str(root/'.agents/skills/playwright/scripts/playwright_cli.sh'),'-s=planet-art-recovery','run-code',code],capture_output=True,text=True);(out/'probe.log').write_text(p.stdout+p.stderr);print(p.stdout[-500:]);p.check_returncode()
